            var sqlCommand = (OracleCommand)command;
            sqlCommand.Parameters.Add(new OracleParameter {
                ParameterName = parameterName,
                OracleDbType = OracleDbType.Object,
                UdtTypeName = "MDSYS.SDO_GEOMETRY",
                Direction = direction,
            });
        }
