I think I found the problem. When using QueryMultiple(Async) with minimum **2 resultsets** like this sample code:

```
public async Task<Profile?> FindByIdAsync(long profileId, CancellationToken ct = default)
{
    await using var connection = CreateConnection();

    const string sql = @"
                SELECT id as Id, role_id as Role, username as Username, email as Email, full_name as FullName, hash as hash, salt as salt, is_email_verified as IsEmailVerified, utc_register_date as UtcRegisterDate, utc_last_login_date as UtcLastLoginDate, email_verify_token as EmailVerifyToken, version as Version FROM profile WHERE id = @id LIMIT 1; 
                SELECT id as Id, token as Token, utc_expire_date as UtcExpireDate FROM refresh_token WHERE profile_id = @profile_id;";

    using var multi =
        await connection.QueryMultipleAsync(sql, new {id = profileId, profile_id = profileId});

    Profile? profile = await multi.ReadSingleOrDefaultAsync<Profile?>();

    if (profile == null)
    {
        return null;
    }

    return profile with { RefreshTokens = await multi.ReadAsync<RefreshToken>()};
}
```

**Notice the method reads the first resultset all-time and the second resultset read is conditional so when a profile does not exist then the method will not read the second resultset. That's the problem if I change the above method to this:**

```
public async Task<Profile?> FindByIdAsync(long profileId, CancellationToken ct = default)
{
    await using var connection = CreateConnection();

    const string sql = @"
                SELECT id as Id, role_id as Role, username as Username, email as Email, full_name as FullName, hash as hash, salt as salt, is_email_verified as IsEmailVerified, utc_register_date as UtcRegisterDate, utc_last_login_date as UtcLastLoginDate, email_verify_token as EmailVerifyToken, version as Version FROM profile WHERE id = @id LIMIT 1; 
                SELECT id as Id, token as Token, utc_expire_date as UtcExpireDate FROM refresh_token WHERE profile_id = @profile_id;";

