    internal static class PropertyCache<T>
    {
        public static readonly (string Name, Type Type, Func<T, object> Accessor)[] OrderedProperties = (
            from prop in typeof(T).GetProperties(BindingFlags.Instance | BindingFlags.Public)
            let dm = prop.GetCustomAttribute<DataMemberAttribute>()
            where dm != null
            orderby dm.Order
            select (prop.Name, Nullable.GetUnderlyingType(prop.PropertyType) ?? prop.PropertyType, GetAccessor(prop))
            ).ToArray();
        static Func<T, object> GetAccessor(PropertyInfo property)
        {
            var p = Expression.Parameter(typeof(T), "p");
            Expression body = Expression.Property(p, property);
            if (property.PropertyType.IsValueType)
                body = Expression.Convert(body, typeof(object));
            return Expression.Lambda<Func<T, object>>(body, p).Compile();
        }
    }

    public static DataTable ConvertToDataTable<TSource>(IEnumerable<TSource> source)
    {
        var props = typeof(TSource).GetProperties();
        var dt = new DataTable();
        foreach (var prop in PropertyCache<TSource>.OrderedProperties)
            dt.Columns.Add(prop.Name, prop.Type);

        if (source != null)
        {
            foreach(var obj in source)
            {
                var newRow = dt.NewRow();
                int col = 0;
                foreach(var prop in PropertyCache<TSource>.OrderedProperties)
                    newRow[col++] = prop.Accessor(obj);
                dt.Rows.Add(newRow);
            }
        }
        return dt;
    }
}

