public class ColumnAttributeTypeMapper<TEntity> : SqlMapper.ITypeMap
{
  private readonly DefaultTypeMap _baseTypeMap = new DefaultTypeMap(typeof(TEntity));
  private readonly IDictionary<string, PropertyInfo> _propertyMap = new Dictionary<string, PropertyInfo>();

  public ColumnAttributeTypeMapper()
  {
    var properties = typeof(TEntity).GetProperties(BindingFlags.Public | BindingFlags.Instance);
    foreach (var property in properties)
      foreach (var attribute in property.GetCustomAttributes<ColumnAttribute>())
        _propertyMap[attribute.Name] = property;
  }

  public ConstructorInfo FindConstructor(string[] names, Type[] types)
  {
    return _baseTypeMap.FindConstructor(names, types);
  }

  public ConstructorInfo FindExplicitConstructor()
  {
    return _baseTypeMap.FindExplicitConstructor();
  }

  public SqlMapper.IMemberMap GetConstructorParameter(ConstructorInfo constructor, string columnName)
  {
    return _baseTypeMap.GetConstructorParameter(constructor, columnName);
  }

  public SqlMapper.IMemberMap GetMember(string columnName)
  {
    return _propertyMap.TryGetValue(columnName, out var mappedProperty)
      ? new DapperProperty(columnName, mappedProperty)
      : _baseTypeMap.GetMember(columnName);
  }

  private class DapperProperty : SqlMapper.IMemberMap
  {
    public string ColumnName { get; }
    public Type MemberType { get; }
    public PropertyInfo Property { get; }
    public FieldInfo Field => null;
    public ParameterInfo Parameter => null;

    public DapperProperty(string columnName, PropertyInfo property)
    {
      ColumnName = columnName;
      MemberType = property.PropertyType;
      Property = property;
    }
  }
}
