{
    var dataSets = new Dictionary<string, DataSet>
    {
        // provide queries and the expected results, this is your stub
        {
            "select top 2 * from hotel",
            new List<Hotel>
            {
                new Hotel { Code = "H-123", HotelId = Guid.NewGuid() },
                new Hotel { Code = "H-456", HotelId = Guid.NewGuid() },
            }.ToDataSet()
        },
        {
            "select * from customer",
            new List<Customer>
            {
                new Customer { Id = 1, Name = "Daniel" }
            }.ToDataSet()
        }
    };

    // the connection is the extension point, setup in your tests
    var conn = new MyDbConnection(dataSets);

    // probably your application code starts like this, pass the connection
    // to whatever you use (IoC, etc)
    conn.Open();
    (await conn.QueryAsync<Hotel>("select top 2 * from hotel")).Dump();
    conn.Query<Customer>("select * from customer").Dump();
}

// Define other methods and classes here
class Hotel
{
    public string Code { get; set; }
    public Guid HotelId { get; set; }
}

class Customer
{
    public int Id { get; set; }
    public string Name { get; set; }
}

public static class MyExtensions
{
    public static DataSet ToDataSet<T>(this IList<T> list)
    {
        Type elementType = typeof(T);
        DataSet ds = new DataSet();
        DataTable t = new DataTable();
        ds.Tables.Add(t);

        // add a column to table for each public property on T
        foreach (var propInfo in elementType.GetProperties())
        {
            Type colType = Nullable.GetUnderlyingType(propInfo.PropertyType) ?? propInfo.PropertyType;

            t.Columns.Add(propInfo.Name, colType);
        }

        // go through each property on T and add each value to the table
        foreach (T item in list)
        {
            DataRow row = t.NewRow();

            foreach (var propInfo in elementType.GetProperties())
            {
                row[propInfo.Name] = propInfo.GetValue(item, null) ?? DBNull.Value;
            }

            t.Rows.Add(row);
        }

        return ds;
    }
}

