@NikitaEmelyanov forgot about this, but since I never heard anything I can share what I did to make this work. First, I made this custom mapper (it's kind of hacky because i'm using the mapper to force all my dates to be UTC with zero offset, but you can modify this to keep the offset that's being passed in):
```
public class DateTimeOffsetTypeHandler : SqlMapper.TypeHandler<DateTimeOffset>
{
	public override void SetValue(IDbDataParameter parameter, DateTimeOffset value)
	{
		parameter.Value = value.ToOffset(TimeSpan.Zero).ToString("dd-MMM-yyyy h:mm:ss tt K");
		parameter.DbType = DbType.String;
	}
	public override DateTimeOffset Parse(object value)
	{
		switch (value)
		{
			case DateTime time:
				return new DateTimeOffset(DateTime.SpecifyKind(time, DateTimeKind.Utc), TimeSpan.Zero);
			case DateTimeOffset dto:
				return dto;
			default:
				throw new InvalidOperationException("Must be DateTime or DateTimeOffset object to be mapped.");
		}
	}
}
```

